def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells:
        return [[0] * w for _ in range(h)]

    index = {p: i for i, p in enumerate(cells)}
    full = (1 << len(cells)) - 1
    pieces = []

    # Pieces are 2x2 squares or three-cell L shapes. The fourth position
    # of an L's bounding box may belong to a neighboring piece.
    for r in range(h - 1):
        for c in range(w - 1):
            box = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            present = [p for p in box if p in index]
            if len(present) == 4:
                mask = sum(1 << index[p] for p in present)
                pieces.append((mask, 1))
            if len(present) >= 3:
                for omitted in range(4):
                    chosen = [p for j, p in enumerate(box)
                              if j != omitted and p in index]
                    if len(chosen) == 3:
                        mask = sum(1 << index[p] for p in chosen)
                        # Missing top-left, top-right, bottom-left, bottom-right
                        color = [2, 4, 3, 1][omitted]
                        pieces.append((mask, color))

    by_cell = [[] for _ in cells]
    for mask, color in pieces:
        for i in range(len(cells)):
            if mask >> i & 1:
                by_cell[i].append((mask, color))
    for options in by_cell:
        options.sort(key=lambda item: (-item[0].bit_count(), item[1]))

    failed = set()

    def solve(remaining):
        if remaining == 0:
            return []
        if remaining in failed:
            return None

        # Choose the remaining cell with the fewest currently available pieces.
        best_i, best_options = None, None
        bits = remaining
        while bits:
            bit = bits & -bits
            i = bit.bit_length() - 1
            options = [p for p in by_cell[i] if p[0] & remaining == p[0]]
            if best_options is None or len(options) < len(best_options):
                best_i, best_options = i, options
                if len(options) <= 1:
                    break
            bits -= bit

        for mask, color in best_options or []:
            result = solve(remaining ^ mask)
            if result is not None:
                return [(mask, color)] + result
        failed.add(remaining)
        return None

    solution = solve(full)
    out = [[0] * w for _ in range(h)]
    if solution is not None:
        for mask, color in solution:
            for i, (r, c) in enumerate(cells):
                if mask >> i & 1:
                    out[r][c] = color
    return out
